mapper.select:
SELECT EXISTS(
SELECT id
FROM ontology
WHERE project_name = #{projectName}
AND version_status = 1  -- 只检查当前版本
AND id != #{excludeId}
)

mapper.update:
UPDATE ontology
SET version_status = #{status}
WHERE project_name = #{projectName}

mapper.insert:
INSERT INTO ontology (
    project_name, creator, version_number, namespace_uri,
    version_status, parent_id, create_time, modify_time
) VALUES (
             #{projectName}, #{creator}, #{versionNumber}, #{namespaceUri},
             #{versionStatus}, #{parentId}, #{createTime}, #{modifyTime}
         )
